"""统一错误信封与领域异常。

HTTP 边界只做一件事：把 ``DomainError`` 转成
``{"error": {"code", "message", "request_id"}}``，避免各模块自己拼响应体。
"""

from __future__ import annotations

import logging
import uuid
from contextvars import ContextVar
from typing import Any

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from sqlalchemy.exc import InterfaceError, OperationalError
from starlette.exceptions import HTTPException as StarletteHTTPException

logger = logging.getLogger(__name__)

# 每个请求一个 ID，错误响应、日志与响应头共用。
request_id_ctx: ContextVar[str] = ContextVar("request_id", default="")


def current_request_id() -> str:
    return request_id_ctx.get() or "unknown"


def request_id_from(request: Request) -> str:
    """读取当前请求 ID。

    ``contextvar`` 在正常请求链路中最快，但未处理异常会越过
    ``RequestContextMiddleware``（其 ``finally`` 已复位 contextvar）后才由最外层
    ``ServerErrorMiddleware`` 处理，此时只能从 ``request.state`` 取。
    """
    value = getattr(request.state, "request_id", "")
    return value or current_request_id()


class DomainError(Exception):
    """可预期的业务异常，必须由 HTTP 层统一转换。"""

    status_code: int = 400
    code: str = "bad_request"

    def __init__(
        self,
        message: str,
        *,
        code: str | None = None,
        status_code: int | None = None,
        details: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message)
        self.message = message
        if code is not None:
            self.code = code
        if status_code is not None:
            self.status_code = status_code
        self.details = details or {}

    def to_envelope(self, request_id: str | None = None) -> dict[str, Any]:
        error: dict[str, Any] = {
            "code": self.code,
            "message": self.message,
            "request_id": request_id or current_request_id(),
        }
        # details 是向后兼容的扩展字段：前端契约只读 code/message/request_id，
        # 需要携带 run_id 等结构化信息时放在 details 里，避免破坏信封形状。
        if self.details:
            error["details"] = self.details
        return {"error": error}


class BadRequestError(DomainError):
    status_code = 400
    code = "bad_request"


class UnauthorizedError(DomainError):
    status_code = 401
    code = "unauthorized"


class ForbiddenError(DomainError):
    status_code = 403
    code = "forbidden"


class CapabilityDisabledError(DomainError):
    status_code = 403
    code = "capability_disabled"


class NotFoundError(DomainError):
    status_code = 404
    code = "not_found"


class ConflictError(DomainError):
    status_code = 409
    code = "conflict"


class PayloadTooLargeError(DomainError):
    status_code = 413
    code = "payload_too_large"


class ValidationFailedError(DomainError):
    status_code = 422
    code = "validation_error"


class RateLimitedError(DomainError):
    status_code = 429
    code = "rate_limited"


class ServiceUnavailableError(DomainError):
    status_code = 503
    code = "service_unavailable"


class RunInProgressError(ConflictError):
    code = "run_in_progress"

    def __init__(self, run_id: str) -> None:
        super().__init__(
            "该会话已有运行中的请求，请等待完成或先停止当前运行",
            details={"run_id": run_id},
        )


class RunNotCancelableError(ConflictError):
    code = "run_not_cancelable"

    def __init__(self, status: str) -> None:
        super().__init__("当前运行已结束，无法取消", details={"status": status})


class ApprovalAlreadyDecidedError(ConflictError):
    code = "approval_already_decided"


class ApprovalExpiredError(ConflictError):
    code = "approval_expired"


def _envelope(
    status_code: int,
    code: str,
    message: str,
    details: dict[str, Any] | None = None,
    *,
    request_id: str | None = None,
) -> JSONResponse:
    error: dict[str, Any] = {
        "code": code,
        "message": message,
        "request_id": request_id or current_request_id(),
    }
    if details:
        error["details"] = details
    return JSONResponse(status_code=status_code, content={"error": error})


def _validation_message(exc: RequestValidationError) -> str:
    """把 FastAPI 的字段错误压缩成一句可读的中文提示。"""
    errors = exc.errors()
    if not errors:
        return "请求参数不合法"
    first = errors[0]
    location = ".".join(str(item) for item in first.get("loc", ()) if item != "body")
    reason = first.get("msg", "参数不合法")
    return f"请求参数不合法：{location} {reason}".strip()


def register_exception_handlers(app: FastAPI) -> None:
    """注册全局异常处理；所有 4xx/5xx 都返回统一信封。"""

    @app.exception_handler(DomainError)
    async def _domain_error(request: Request, exc: DomainError) -> JSONResponse:
        request_id = request_id_from(request)
        if exc.status_code >= 500:
            logger.exception("业务异常：%s", exc.message, extra={"request_id": request_id})
        else:
            logger.info(
                "业务异常：%s code=%s", exc.message, exc.code, extra={"request_id": request_id}
            )
        return JSONResponse(
            status_code=exc.status_code, content=exc.to_envelope(request_id=request_id)
        )

    @app.exception_handler(RequestValidationError)
    async def _validation_error(request: Request, exc: RequestValidationError) -> JSONResponse:
        return _envelope(
            422,
            "validation_error",
            _validation_message(exc),
            request_id=request_id_from(request),
        )

    @app.exception_handler(StarletteHTTPException)
    async def _http_error(request: Request, exc: StarletteHTTPException) -> JSONResponse:
        code_map = {
            400: "bad_request",
            401: "unauthorized",
            403: "forbidden",
            404: "not_found",
            405: "method_not_allowed",
            409: "conflict",
            413: "payload_too_large",
            422: "validation_error",
            429: "rate_limited",
            503: "service_unavailable",
        }
        code = code_map.get(exc.status_code, "http_error")
        message = str(exc.detail) if exc.detail else "请求失败"

                terminal = true
                ctrl.abort()
              }
            },
            // 让库停止自动重试，由外层 loop 用最新 lastSeq 重连。
            onerror: (err) => {
              throw err
            },
          },
        )
      } catch (err) {
        if (terminal || ctrl.signal.aborted) return
        const status = (err as { status?: number }).status
        const code = (err as { code?: string }).code

        if (status === 401) {
          // 先刷新 access token（替换为项目现有 refresh 实现）；刷新失败再登出，不要无限重连。
          const refreshed = await refreshAccessToken()
          if (!refreshed) return handlers.onFatal('登录已过期')
          accessToken = refreshed
          retryDelay = 300
          continue
        }
        if (status === 404) {
          return handlers.onFatal('运行不存在或无权访问')
        }
        if (status === 403) {
          // 续流端点不要求管理员，403 属通用拒绝（当前正常路径不会出现），按不可恢复处理。
          return handlers.onFatal('无权访问该运行')
        }
        if (status === 400 && code === 'replay_too_large') {
          return handlers.onFatal('待回放事件过多，请先用 /runs/{id}/events 分页回放已落库历史')
        }
        if (status === 422) {
          return handlers.onFatal('续流参数非法（after_seq 必须是 >=0 的整数）')
        }

        // 网络错误 / 5xx / 429：指数退避后用最新 lastSeq 重连（只补已落库事件，delta 不补）。
        await sleep(retryDelay + Math.random() * 200)
        retryDelay = Math.min(retryDelay * 2, 5000)
        continue
      }

      // 正常 EOF：若还没收到终态事件，先查一次 run 状态再决定是否重连。
      if (!terminal && !ctrl.signal.aborted) {
        // 服务端对「已终态且回放里没有终态事件」的 run 会回放完直接关闭：
        // 此时重连只会每 5 秒空转，必须停止重连并刷新终态。
        const status = await fetchRunStatus().catch(() => null)
        if (status === 'succeeded' || status === 'failed' || status === 'canceled') {
          handlers.onRunEnd?.(status)
          return
        }
        // 仍为 running/interrupted 或状态查询失败：按最后 seq 退避重连。
        await sleep(retryDelay + Math.random() * 200)
        retryDelay = Math.min(retryDelay * 2, 5000)
        continue
      }
      return
    }
  }

  void loop()
  return { close: () => ctrl.abort(), getLastSeq: () => lastSeq }
}
```

说明：

- 每收到一帧就把 `ev.id` 记为 `lastSeq`（`id` 就是 `seq`，纯数字）；重连时作为 `after_seq`，
  服务端只回放 `seq > after_seq` 的已落库事件。示例在 `onmessage` 里显式丢弃 `seq <= lastSeq`
  的重复帧，防止重连窗口导致消息重复。
- 收到 `message.done` / `error`：属于终态事件，**不要重连**；UI 以 `GET /api/v1/runs/{id}` 的终态为准，
  并用 `GET /api/v1/conversations/{id}/messages` 拉取助手消息终稿，覆盖本地累积的增量文本。
- EOF 且未收到终态事件时分两种：
  1. **run 已终态**（`succeeded`/`failed`/`canceled`）但回放里没有终态事件：服务端回放完就关闭，
     示例会先查 `GET /runs/{id}`，命中终态则停止重连并回调 `onRunEnd`；
  2. **run 仍运行 / `interrupted`**（或状态查询失败）：按最后 `seq` 退避重连；`interrupted` 连上后
     继续等审批恢复。
- 单实例部署：后端事件总线是进程内实现。多实例/重部署时实时帧可能丢失，重连后的回放只能补齐
  **已落库**事件；`message.delta`/`reasoning.delta` 不落库，断线窗口的增量文本不补，需在 run
  进入终态后靠消息历史终稿覆盖（`interrupted` 期间历史接口不返回该消息）。

### 2.3 用原生 `fetch` 接入（无第三方依赖）

关键点：`fetch` 的 `response.body` 是 `ReadableStream`，按 `\n\n` 切帧；跳过 `:` 开头的注释帧；
`data:` 行拼成 JSON。示例只保留骨架：

```ts
const response = await fetch(
  `${baseUrl}/api/v1/runs/${runId}/stream?after_seq=${lastSeq}`,
  {
    headers: { Authorization: `Bearer ${accessToken}`, Accept: 'text/event-stream' },
    signal: abortController.signal,
  },
)

if (!response.ok) {
  const body = await response.json().catch(() => null)
  // 错误信封：{ error: { code, message, request_id, details? } }，见 docs/api.md §1。
  throw Object.assign(new Error(body?.error?.message ?? '续流失败'), {
    status: response.status,
    code: body?.error?.code,
  })
}

const reader = response.body!.getReader()
const decoder = new TextDecoder()
let buffer = ''

while (true) {
  const { value, done } = await reader.read()
  if (done) break
  buffer += decoder.decode(value, { stream: true })

  let boundary = buffer.indexOf('\n\n')
  while (boundary >= 0) {
    const block = buffer.slice(0, boundary)
    buffer = buffer.slice(boundary + 2)
    // 注释帧（: ping）没有字段，直接忽略；其余帧解析 id/event/data。
    const lines = block.split('\n').filter((line) => line && !line.startsWith(':'))
    const frame: Record<string, string> = {}
    for (const line of lines) {
      const [field, ...rest] = line.split(':')
      frame[field] = rest.join(':').trim()
    }
    if (frame.id) lastSeq = Number(frame.id)
    if (frame.data) {
      const data = JSON.parse(frame.data)
      if (frame.event === 'message.done' || frame.event === 'error') terminal = true
    }
    boundary = buffer.indexOf('\n\n')
  }
}
